package e.e.a;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.preference.*;import android.widget.Toast;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Portable user settings, with typed validation before a single atomic import. */
public final class SettingsBackup {
 static final ExecutorService WORK=Executors.newSingleThreadExecutor();static final Handler MAIN=new Handler(Looper.getMainLooper());
 static final Map<String,String> TYPES=SettingsBackupData.TYPES;static final Map<String,Set<String>> VALUES=SettingsBackupData.VALUES;
 static String tr(Context c,String j,String e,String z){return PanelUi.tr(c,j,e,z);}
 static boolean portable(String k){return k!=null&&!k.matches("(?i).*(cookie|session|password|token|auth).*|cache_tree.*|cache_dir|nologin|user_id|login_.*|save_.*|labs_.*|nicoid_patch_version|nicoid_share_debug");}
 static void collect(PreferenceGroup root){for(int i=0;i<root.getPreferenceCount();i++){Preference p=root.getPreference(i);if(p instanceof PreferenceGroup){collect((PreferenceGroup)p);continue;}String k=p.getKey();if(!portable(k)||k.startsWith("nicoid_backup"))continue;TYPES.put(k,p instanceof TwoStatePreference?"boolean":p instanceof MultiSelectListPreference?"set":"string");if(p instanceof ListPreference){Set<String> values=new HashSet<>();for(CharSequence v:((ListPreference)p).getEntryValues())values.add(v.toString());VALUES.put(k,values);}}}
 public static void install(PreferenceActivity a){PreferenceGroup root=a.getPreferenceScreen();if(root==null||a.findPreference("nicoid_backup")!=null)return;Preference old=a.findPreference("nicoid_backup_placeholder");if(old==null)old=a.findPreference("labs");int order=old==null?root.getPreferenceCount():old.getOrder();if(old!=null){PreferenceGroup parent=SettingsTools.parent(root,old);if(parent!=null)parent.removePreference(old);}PreferenceCategory category=new PreferenceCategory(a);category.setKey("nicoid_backup");category.setTitle(tr(a,"設定のバックアップ","Settings backup","設定備份"));category.setOrder(order);root.addPreference(category);for(int i=0;i<2;i++){final boolean export=i==0;Preference p=new Preference(a);p.setKey(export?"nicoid_backup_export":"nicoid_backup_import");p.setTitle(tr(a,export?"設定をエクスポート":"設定をインポート",export?"Export settings":"Import settings",export?"匯出設定":"匯入設定"));p.setOnPreferenceClickListener(v->{collect(root);pick(a,export);return true;});category.addPreference(p);}collect(root);SharedPreferences pref=PreferenceManager.getDefaultSharedPreferences(a);SharedPreferences.Editor edit=pref.edit();for(String k:pref.getAll().keySet())if(k.startsWith("labs_"))edit.remove(k);edit.apply();}
 static void pick(Activity a,boolean export){try{FragmentManager manager=a.getFragmentManager();Picker p=(Picker)manager.findFragmentByTag("settings-backup");if(p==null){p=new Picker();manager.beginTransaction().add(p,"settings-backup").commit();manager.executePendingTransactions();}p.pick(export);}catch(Exception e){Toast.makeText(a,tr(a,"ファイル選択画面を開けませんでした","Unable to open file picker","無法開啟檔案選擇器"),1).show();}}
 static JSONObject encode(Map<String,?> values)throws Exception{return SettingsBackupData.encode(values);}
 static Map<String,Object> decode(JSONObject file)throws Exception{return SettingsBackupData.decode(file);}
 static void known(SharedPreferences p){TYPES.put(PopupGestures.KEY,"boolean");for(String k:new String[]{"search_range_from","search_range_to"})TYPES.put(k,"long");for(String k:new String[]{"search_range_min","search_range_max","search_range_mode"})TYPES.put(k,"int");for(String k:new String[]{"search_Time","search_Date","search_Sort"})TYPES.put(k,"int");for(String k:new String[]{"nicoid_content_filter_rules","nicoid_content_rules_v2","nicoid_content_keywords","nicoid_content_channels"})TYPES.put(k,"string");for(Map.Entry<String,?> e:p.getAll().entrySet())if(TYPES.containsKey(e.getKey())){Object v=e.getValue();TYPES.put(e.getKey(),v instanceof Boolean?"boolean":v instanceof Integer?"int":v instanceof Long?"long":v instanceof Float?"float":v instanceof Set?"set":"string");}}
 static boolean apply(SharedPreferences p,Map<String,Object> values){SharedPreferences.Editor edit=p.edit();for(Map.Entry<String,Object> e:values.entrySet()){String k=e.getKey();Object v=e.getValue();if(v instanceof Boolean)edit.putBoolean(k,(Boolean)v);else if(v instanceof Integer)edit.putInt(k,(Integer)v);else if(v instanceof Long)edit.putLong(k,(Long)v);else if(v instanceof Float)edit.putFloat(k,(Float)v);else if(v instanceof Set)edit.putStringSet(k,(Set<String>)v);else edit.putString(k,(String)v);}return edit.commit();}
 public static final class Picker extends Fragment {boolean busy;void pick(boolean export){if(busy)return;Intent i=new Intent(export?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(export?"application/json":"*/*");if(export)i.putExtra(Intent.EXTRA_TITLE,"nicoid-re-settings-"+new java.text.SimpleDateFormat("yyyyMMdd-HHmmss",Locale.ROOT).format(new Date())+".json");busy=true;try{startActivityForResult(i,export?61:62);}catch(ActivityNotFoundException e){busy=false;throw e;}}public void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);busy=false;Activity a=getActivity();if(a==null||result!=Activity.RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();SharedPreferences pref=PreferenceManager.getDefaultSharedPreferences(a);known(pref);WORK.execute(()->{try{if(req==61){byte[] bytes=encode(pref.getAll()).toString(2).getBytes("UTF-8");try(OutputStream out=a.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(bytes);}MAIN.post(()->Toast.makeText(a,tr(a,"設定をエクスポートしました","Settings exported","已匯出設定"),1).show());}else{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(bytes.size()+n>2*1024*1024)throw new IOException("File too large");bytes.write(buffer,0,n);}}Map<String,Object> values=decode(new JSONObject(bytes.toString("UTF-8")));MAIN.post(()->{if(a.isFinishing())return;AlertDialog d=UiDialogs.builder(PlaybackSession.dialogContext(a)).setTitle(tr(a,"設定をインポート","Import settings","匯入設定")).setMessage(tr(a,"設定を復元します。反映後にアプリを再起動してください。","Restore settings, then restart the app.","還原設定後請重新啟動應用程式。")+"\n"+values.size()+tr(a,"項目"," settings"," 個項目")).setPositiveButton(tr(a,"インポート","Import","匯入"),(x,w)->WORK.execute(()->{boolean ok=apply(pref,values);MAIN.post(()->{Toast.makeText(a,tr(a,ok?"設定をインポートしました。アプリを再起動してください":"設定を保存できませんでした",ok?"Settings imported. Restart the app.":"Unable to save settings",ok?"已匯入設定，請重新啟動應用程式":"無法儲存設定"),1).show();if(ok)a.recreate();});})).setNegativeButton(tr(a,"キャンセル","Cancel","取消"),null).create();PlaybackSession.showDialog(d);});}}catch(Exception e){MAIN.post(()->Toast.makeText(a,tr(a,req==61?"エクスポートに失敗しました":"設定ファイルを読み込めませんでした",req==61?"Unable to export settings":"Unable to read settings file",req==61?"匯出設定失敗":"無法讀取設定檔"),1).show());}});}}
}
